# region: digest
def digest(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs, offset=4):
    return [v + offset for v in xs]

# region: shape
def shape(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: gather
def gather(xs):
    return [v * v for v in xs[1:]]

# region: sift
def sift(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: emit
def emit(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return emit(sift(gather(shape(intake(digest(raw))))))

